import{z as o,x as i,o as A,c as s,q as e,j as B,D as a,d as l,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多 token 预测的训练","description":"","frontmatter":{"title":"多 token 预测的训练","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-mtp-training.md","filePath":"llm/spec-mtp-training.md","lastUpdated":1791413859000}'),p={name:"llm/spec-mtp-training.md"};function D(d,E,h,m,c,C){const t=i("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="多-token-预测的训练" tabindex="-1">多 token 预测的训练 <a class="header-anchor" href="#多-token-预测的训练" aria-label="Permalink to &quot;多 token 预测的训练&quot;">​</a></h1><div class="epigraph"><p>接受率是测出来的，更是训出来的：草稿每高一分对齐，都是数据与损失函数提前付过的钱。</p><footer>—— 据 Cai et al., Medusa, ICML 2024 与 DeepSeek-V3 技术报告的训练口径整理</footer></div><p><a href="/llm/spec-acceptance-theory">上一课</a>把 \\(\\alpha\\) 定义成分布重叠；本课往上游走一步：重叠是训练买来的。前面各课把草稿当现成件，自蒸馏与特征回放都一笔带过；本课把「为投机而训」钉成一课：损失怎么设计、数据怎么配、什么时候训。<a href="/llm/multi-token-prediction-training">Multi-Token Prediction 训练目标</a>写预训练目标本身，<a href="/llm/mtp">MTP</a> 写 DeepSeek-V3 的模块结构；本课写工程全链——从目标选型到上线前的接受率验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>草稿训练有一个共同形状：目标已冻结或定型，草稿在它的输出上学习。三个决策定 \\(\\alpha\\) 的上限。<strong>损失</strong>：只对齐下一词，多步能力靠推理时的树去碰运气；显式监督未来 \\(k\\) 个位置，表示被迫含远位信息——Gloeckle 等人的多头损失是前者的补救，MTP 与 EAGLE-3 的训练时间测试是后者的兑现。<strong>数据</strong>：草稿在什么分布上训，就在什么分布上好——通用对话喂不出代码桶的高接受率，目标过 RLHF 后草稿还在旧策略输出上训，重叠先掉一截。<strong>时机</strong>：跟预训练一起（成本一次性、换目标作废）、跟随微调（跟得上策略漂移）、或部署前补训（灵活但容易被数据卡脖子）。三件事互相牵制。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按介入深度排三条路线。<strong>部署后挂头</strong>（Medusa-1 式）：骨干冻结，头在目标自己的输出上自蒸馏；数据由目标生成再过滤，分布自动对齐，骨干零风险；上限是头的容量与 \\(h_t\\) 的远位信息量。<strong>联合训练</strong>（Medusa-2 式）：头损失与下一词损失同训，须护住骨干——学习率分段、蒸馏正则，防头任务把主任务拖下水；好处是表示被迫适配多步预测，远位头更强。<strong>预训练期 MTP</strong>（DeepSeek-V3 式）：顺序模块对每个位置稠密监督未来若干步，teacher forcing 下这些监督项近乎免费；推理时可整段卸掉、也可留作投机草稿。特征级草稿单列一路：在目标隐状态的回放记录上训一层解码器，<a href="/llm/eagle-3">EAGLE-3</a> 的 training-time test 把「草稿吃自己的输出」写进训练分布。<strong>验收</strong>：上线前在真实流量分桶上测 \\(\\alpha\\) 与 \\(\\tau\\)——按<a href="/llm/spec-acceptance-theory">接受率的理论与测量</a>的协议，而不是只看训练损失的验证集。</p><p><span class="marginnote">术语翻译：「自蒸馏」就是让模型当自己的老师——用冻结目标模型自己的输出当教材，去训挂在它身上的头。教材与考题（真实流量）天然同源，分布自动对齐，这是这条路线便宜又稳的根本原因。</span></p>',8)),(A(),B(n,null,{default:a(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%7B%22%E4%BB%8B%E5%85%A5%E6%B7%B1%E5%BA%A6%3F%22%7D%20--%3E%20POST%5B%22%E9%83%A8%E7%BD%B2%E5%90%8E%E6%8C%82%E5%A4%B4%EF%BC%9A%E5%86%BB%E7%BB%93%E9%AA%A8%E5%B9%B2%20%2B%20%E8%87%AA%E8%92%B8%E9%A6%8F%22%5D%0A%20%20GOAL%20--%3E%20JOINT%5B%22%E8%81%94%E5%90%88%E8%AE%AD%E7%BB%83%EF%BC%9A%E5%A4%B4%E6%8D%9F%E5%A4%B1%20%2B%20%E6%8A%A4%E9%AA%A8%E5%B9%B2%22%5D%0A%20%20GOAL%20--%3E%20PRE%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%E6%9C%9F%20MTP%EF%BC%9A%E7%A8%A0%E5%AF%86%E8%BF%9C%E4%BD%8D%E7%9B%91%E7%9D%A3%22%5D%0A%20%20POST%20--%3E%20DATA%5B%22%E6%95%B0%E6%8D%AE%EF%BC%9A%E5%AF%B9%E9%BD%90%E6%9C%8D%E5%8A%A1%E6%B5%81%E9%87%8F%E5%88%86%E6%A1%B6%22%5D%0A%20%20JOINT%20--%3E%20DATA%0A%20%20PRE%20--%3E%20DATA%0A%20%20DATA%20--%3E%20EVAL%5B%22%E4%B8%8A%E7%BA%BF%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%88%86%E6%A1%B6%E6%B5%8B%20%CE%B1%20%E4%B8%8E%20%CF%84%22%5D%0A%20%20EVAL%20--%3E%20SHIP%7B%22%E8%BE%BE%E6%A0%87%3F%22%7D%0A%20%20SHIP%20--%3E%7C%22%E6%98%AF%22%7C%20GO2%5B%22%E8%BF%9B%E6%9C%8D%E5%8A%A1%EF%BC%8C%E6%8E%A5%E5%9C%A8%E7%BA%BF%E6%A1%B6%E8%B4%A6%22%5D%0A%20%20SHIP%20--%3E%7C%22%E5%90%A6%22%7C%20LOOP%5B%22%E6%8D%A2%E6%8D%9F%E5%A4%B1%20%2F%20%E8%A1%A5%E6%95%B0%E6%8D%AE%EF%BC%8C%E9%87%8D%E8%AE%AD%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三条路线的机制差异在「远位信息从哪来」。冻结骨干时，\\(h_t\\) 只被下一词损失塑造过，远位头是在榨表示里偶然残留的信息——这就是<a href="/llm/spec-self-draft-medusa">自投机与多 token 头</a>里「位置每远一步对齐掉一截」的训练侧根源；联合训练让梯度改表示，把「多 token 可预测」买进权重，抬高远位天花板，代价是主任务风险。预训练期 MTP 更早：表示成形时就带远位监督，交换的是预训练算力与参数。数据侧的机制与<a href="/llm/spec-acceptance-theory">接受率的理论与测量</a>的 \\(\\mathrm{TV}\\) 视角直通：训练分布偏移让 \\(q\\) 的峰整体搬离 \\(p\\) 的峰，\\(\\alpha\\) 掉的正是那份质量；数据配比按服务流量的桶来，代码桶用代码喂。EAGLE-3 的机制则指出损失设计的反直觉处：显式回归目标特征会在多步时把草稿按在流形上，数据越多越平；放开约束、对齐多步输入分布，缩放才回来。</p><p><span class="marginnote">一个便宜的验收数字：上线前对每个流量桶各抽几百条，跑草稿记逐位置 \\(\\hat\\alpha\\) 与实现的 \\(\\tau\\)。训练验证集上的损失降了不等于桶上 \\(\\alpha\\) 升了——损失是平均，重叠可以被平均掩盖。</span></p><p><span class="marginnote">数字实例：目标过 RLHF 后风格变了三成，草稿还停在旧输出上训，\\(\\alpha\\) 从 0.8 掉到 0.6——\\(\\gamma=4\\) 的期望前进长度就从约 3.36 掉到约 2.31，加速比缩水约三成。策略一漂移，补训要按版本排队，道理就在这笔账上。</span></p>',4)),(A(),B(n,null,{default:a(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%9C%E4%BD%8D%E4%BF%A1%E6%81%AF%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%5D%20--%3E%20R1%5B%22%E9%83%A8%E7%BD%B2%E5%90%8E%E6%8C%82%E5%A4%B4%3A%20%E6%A6%A8%E5%86%BB%E7%BB%93%E8%A1%A8%E7%A4%BA%E9%87%8C%E7%9A%84%E6%AE%8B%E7%95%99%22%5D%0A%20%20Q%20--%3E%20R2%5B%22%E8%81%94%E5%90%88%E8%AE%AD%E7%BB%83%3A%20%E6%A2%AF%E5%BA%A6%E6%94%B9%E8%A1%A8%E7%A4%BA%2C%20%E4%B9%B0%E8%BF%9B%E6%9D%83%E9%87%8D%22%5D%0A%20%20Q%20--%3E%20R3%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%E6%9C%9F%20MTP%3A%20%E8%A1%A8%E7%A4%BA%E6%88%90%E5%BD%A2%E6%97%B6%E5%B8%A6%E8%BF%9C%E4%BD%8D%E7%9B%91%E7%9D%A3%22%5D%0A%20%20R1%20--%3E%20C1%5B%22%E9%9B%B6%E9%AA%A8%E5%B9%B2%E9%A3%8E%E9%99%A9%2C%20%E5%A4%A9%E8%8A%B1%E6%9D%BF%E6%9C%80%E4%BD%8E%22%5D%0A%20%20R2%20--%3E%20C2%5B%22%E5%A4%A9%E8%8A%B1%E6%9D%BF%E8%BE%83%E9%AB%98%2C%20%E9%A1%BB%E6%8A%A4%E4%BD%8F%E4%B8%BB%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20R3%20--%3E%20C3%5B%22%E4%B8%8A%E9%99%90%E6%9C%80%E9%AB%98%2C%20%E4%BD%86%E7%BB%91%E5%AE%9A%E6%9E%B6%E6%9E%84%E4%B8%8E%E9%A2%84%E8%AE%AD%E7%BB%83%E7%AE%97%E5%8A%9B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预训练期 MTP 增加参数与显存，且绑定架构：换基座重训，插件化草稿没有这个包袱。联合训练的超参是雷区，头损失权重过大直接显形在主任务指标上——验收要把基座质量与投机收益分开报。RLHF 后的策略漂移会让早期训练的草稿掉接受率，补训时机按策略版本排。最后别混淆对象：MTP 作为训练目标给表示加远位监督，模块留作推理草稿只是副产品；EAGLE 与 Medusa 族仍是部署后路线，成本结构与上限不同源，选型按手头能改什么定。</p><p><span class="marginnote">术语翻译：teacher forcing 指训练时每一步都喂标准答案、而不是模型自己上一步的输出，错误不滚雪球、监督信号稳定。反过来看，推理时草稿要吃自己的输出——这正是 training-time test 要专门把这种情形写进训练的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>草稿的 \\(\\alpha\\) 上限由三个训练决策定：损失（是否显式监督远位）、数据（对齐服务流量分桶）、时机（预训练/微调/部署前）。</li><li>三条介入路线：冻结骨干挂头自蒸馏、联合训练抬天花板但护骨干、预训练期 MTP 把远位买进权重。</li><li>数据偏移按 \\(\\mathrm{TV}\\) 机制吃掉重叠：代码桶的接受率要靠代码数据喂出来。</li><li>EAGLE-3 的教训：约束性损失会在多步上压平缩放，对齐多步输入分布比加数据先发生。</li><li>上线验收按桶测 \\(\\hat\\alpha\\) 与 \\(\\tau\\)，训练损失不替代重叠测量。</li><li>出处：Cai et al., ICML 2024；Li et al., EAGLE 系列 2024–2025；DeepSeek-V3 技术报告， arXiv:2412.19437；Gloeckle et al., 2024。</li></ul>',5))])}const F=o(p,[["render",D]]);export{_ as __pageData,F as default};
